import json
import re

raw_lyrics = json.load(open('full_genius_lyrics.json', encoding='utf-8'))

def clean_txt(t):
    return re.sub(r'[^a-zA-Z0-9äöüÄÖÜß]', '', t).lower()

def check_quote_in_track(quote, track_text):
    # Split quote by slash or ellipsis if multi-line
    parts = [p.strip() for p in re.split(r'[/–—]', quote) if p.strip()]
    track_clean = clean_txt(track_text)
    for p in parts:
        p_clean = clean_txt(p)
        if len(p_clean) >= 4 and p_clean not in track_clean:
            return False, p
    return True, ""

