# Run rigorous verification
all_passed = True
for t_num in sorted(reviews_de.keys()):
    rev = reviews_de[t_num]
    track_text = raw_lyrics[t_num]["full_text"]
    
    # Extract all quotes inside lyric-quote-highlight
    quotes = re.findall(r'<span class="lyric-quote-highlight">„?(.*?)“?</span>', rev)
    for q in quotes:
        # Strip German quotes if present
        q_clean = q.replace('„', '').replace('“', '').replace('"', '').replace('&quot;', '')
        ok, bad_part = check_quote_in_track(q_clean, track_text)
        if not ok:
            print(f"[ERROR] Track {t_num} has INVALID quote: '{bad_part}' from full quote '{q}'")
            all_passed = False
        else:
            print(f"[OK] Track {t_num} quote verified: '{q_clean[:40]}...'")

if all_passed:
    print("\n>>> ALL 11 GERMAN REVIEWS PASS 100% VERBATIM LYRICS VERIFICATION! <<<")
else:
    print("\n>>> VERIFICATION FAILED! <<<")
